extern void *D_8013D168[];
extern void *D_8013D16C[];
extern void applyFrameVelocityX(GameObject *);

void func_80134B88(GameObject *o)
{
    switch (o->subState) {
    case 0:
        if (GAME.selectedArea == 1 && GAME.selectedSection < 2) break;
        switch (o->step) {
        case 0:
            o->timer = 0x3c;
            o->movetab = ((char *)&D_800771FC);
            o->anim = D_8013D168[0];
            readAnimFrameCount(o);
            o->step++;
        case 1:
            tickAnimation(o);
            applyFrameVelocityX(o);
            if (--o->timer <= 0) {
                o->anim = D_8013D16C[0];
                readAnimFrameCount(o);
                o->step++;
            }
            break;
        case 2:
            if (tickAnimation(o)) {
                o->step = 0;
                o->animFrame ^= 1;
            }
            break;
        }
        break;
    case 1:
        if (GAME.selectedArea == 1 && GAME.selectedSection < 2) break;
        if (o->step == 0) {
            o->objectIndex = o->animFrame;
            o->animFrame = o->h->p.whole > (*(Fix16 **)&PLAYER.obj.h)->p.whole;
            o->anim = D_8013D16C[0];
            readAnimFrameCount(o);
            o->step++;
        }
        break;
    }
}

